CREATE VIEW "public"."act_inventario_vigente" AS (select "act_activos"."id", "act_activos"."fila_origen_id", "act_activos"."origen", "act_activos"."numero_origen", "act_activos"."codigo", "act_activos"."codigo_historico", "act_activos"."descripcion", "act_activos"."estado", "act_activos"."ubicacion", "act_activos"."responsable", "act_activos"."acta", "act_activos"."observaciones", "act_activos"."comentario", "act_activos"."grupo_contable", "act_activos"."grupo_contable_codigo", "act_activos"."auxiliar_grupo", "act_activos"."auxiliar_grupo_alterno", "act_activos"."vida_util", "act_activos"."porcentaje_depreciacion", "act_activos"."costo_historico", "act_activos"."costo_migrado", "act_activos"."costo_final_actualizado", "act_activos"."depreciacion_gestion", "act_activos"."depreciacion_acumulada", "act_activos"."valor_neto", "act_activos"."fecha_historica", "act_activos"."fecha_migracion", "act_activos"."indicador_r", "act_activos"."rube", "act_activos"."incidencias_importacion", "act_activos"."creado_en", "act_filas_importadas"."fila_excel", "act_hojas_importadas"."nombre" from "act_activos" inner join "act_filas_importadas" on "act_activos"."fila_origen_id" = "act_filas_importadas"."id" inner join "act_hojas_importadas" on "act_filas_importadas"."hoja_id" = "act_hojas_importadas"."id" where "act_hojas_importadas"."vigencia" = 'vigente');